static void translation_clear(struct em_translation *members)
{
	members->state = (struct neocc_translation){ 0 };
}

static int translation_open(struct object *self, const struct vr *caller_context)
{
	OBS_OBJECT_OPEN_;
	if (self->ref_count == 1)
		translation_clear(self->members);
	return R_P;
}

static int translation_close(struct object *self,
	const struct vr *caller_context)
{
	struct em_translation *members = self->members;

	OBS_OBJECT_CLOSE_;
	if (!self->ref_count)
		translation_clear(members);
	return R_P;
}

static int translation_interact0(struct object *self, unsigned int action,
	const struct vr *caller_context)
{
	struct em_translation *members = self->members;

	if (action != NEOCC_AC0_TRANSLATION_RESET) {
		SBO_OBJECT_INTERACT0;
	}

	if (!self->ref_count)
		return RN_INVALIDARG;
	translation_clear(members);
	return R_P;
}

